@utility btn-solid {
  color: var(--btn-fg);
  background-color: var(--btn-color);
  --btn-focus-outline-color: color-mix(in oklab, var(--btn-color) 65%, transparent);
  background-image: radial-gradient(farthest-corner at 50% -50%, rgba(255, 255, 255, .1) 0%, transparent 100%);
  box-shadow:
    inset 0 1px 0 color-mix(in oklab, white 22%, transparent),
    inset 0 -1px 0 color-mix(in oklab, black 18%, transparent);

  &:hover {
    background-color: color-mix(in oklab, var(--btn-color) 88%, black);
  }

  &:active {
    background-color: color-mix(in oklab, var(--btn-color) 78%, black);
  }
}

@utility btn-outline {
  color: var(--btn-fg);
  background-color: var(--btn-color);
  border-color: var(--btn-border-color);
  --btn-focus-outline-color: var(--btn-ring-color);
  border-width: 1px;
  border-style: solid;
  box-shadow: 0 1px 2px color-mix(in oklab, black 10%, transparent);

  &:hover {
    background-color: var(--btn-hover-color);
  }

  &:active {
    background-color: var(--btn-active-color);
  }
}

@utility btn-soft {
  color: var(--btn-fg);
  background-color: color-mix(in oklab, var(--btn-color) 10%, transparent);
  --btn-focus-outline-color: color-mix(in oklab, var(--btn-color) 55%, transparent);

  &:hover {
    background-color: color-mix(in oklab, var(--btn-color) 16%, transparent);
  }

  &:active {
    background-color: color-mix(in oklab, var(--btn-color) 22%, transparent);
  }
}

@utility btn-ghost {
  color: var(--btn-fg);
  --btn-focus-outline-color: var(--btn-ring-color);

  &:hover {
    background-color: var(--btn-hover-color);
  }

  &:active {
    background-color: var(--btn-active-color);
  }
}

